(()=>{'use strict';
const $=(s,r=document)=>r.querySelector(s),$$=(s,r=document)=>[...r.querySelectorAll(s)];
const catalog={product:[{id:'DEMO-PRODUCT-001',code:'DEMO-P001',name:'演示产品A',spec:'标准规格A',type:'自制'},{id:'DEMO-PRODUCT-002',code:'DEMO-P002',name:'演示产品B',spec:'标准规格B',type:'外购'},{id:'DEMO-PRODUCT-003',code:'DEMO-P003',name:'演示产品C',spec:'标准规格C',type:'自制'}],process:[{id:'DEMO-PROCESS-001',code:'DEMO-PROC001',name:'演示工序A'},{id:'DEMO-PROCESS-002',code:'DEMO-PROC002',name:'演示工序B'}],vendor:[{id:'DEMO-VENDOR-001',code:'DEMO-SUP001',name:'演示供应商A'},{id:'DEMO-VENDOR-002',code:'DEMO-SUP002',name:'演示供应商B'}]};
let layer=null,anchor=null,kind='',query='',visible=[],active=0,exportMenu=null;
const caption=r=>kind==='product'?r.code+' - '+r.name+' - '+r.spec:r.name;
function close(){const wasOpen=!!layer;layer?.remove();layer=null;anchor?.setAttribute('aria-expanded','false');if(wasOpen&&anchor)$('input',anchor)?.focus();}
function choose(record){if(!anchor)return;const input=$('input',anchor);input.dataset.v31Entity=record?.id||'';const item=$('.kodo-new-select-selection-item',anchor);if(item){item.textContent=record?caption(record):'';item.title=record?caption(record):'';}anchor.dataset.v31Selected=record?.id||'';const ph=$('.kodo-new-select-selection-placeholder',anchor);if(ph)ph.hidden=!!record;let clear=$('[data-v31-clear]',anchor);if(clear)clear.hidden=!record;close();input.focus();}
function paint(){const list=$('[data-v31-options]',layer);visible=catalog[kind].filter(r=>(r.id+' '+r.code+' '+r.name+' '+(r.spec||'')).toLowerCase().includes(query.toLowerCase()));active=Math.max(0,Math.min(active,visible.length-1));list.replaceChildren();if(!visible.length){const e=document.createElement('div');e.setAttribute('role','status');e.className='v31-empty';e.textContent='暂无数据';list.append(e);}visible.forEach((r,i)=>{const e=document.createElement('div');e.className='kodo-new-select-item kodo-new-select-item-option'+(i===active?' kodo-new-select-item-option-active':'');e.setAttribute('role','option');e.setAttribute('aria-selected',String(anchor.dataset.v31Selected===r.id));e.dataset.v31Entity=r.id;e.id='v31-option-'+i;e.title=caption(r);const text=document.createElement('div');text.className='kodo-new-select-item-option-content';text.textContent=caption(r);e.append(text);list.append(e);});const search=$('input',layer);search.setAttribute('aria-activedescendant',visible.length?'v31-option-'+active:'');const clear=$('.kodo-new-input-clear-icon',layer);if(clear)clear.hidden=!query;}
function open(control,type){close();exportMenu?.remove();exportMenu=null;anchor=control;kind=type;query='';active=0;const h=document.createElement('div');h.innerHTML=window.REVIEWED_V31_ASSETS.dropdown;layer=h.firstElementChild;layer.dataset.v31Picker='';const rect=control.getBoundingClientRect();layer.style.cssText='position:fixed;z-index:2300;left:'+rect.x+'px;top:'+(rect.bottom+4)+'px;width:'+rect.width+'px;min-width:210px';document.body.append(layer);anchor.setAttribute('aria-expanded','true');const search=$('input',layer);search.value='';search.setAttribute('aria-label','搜索字段');search.setAttribute('role','combobox');search.setAttribute('aria-expanded','true');search.setAttribute('aria-controls','v31-options');search.tabIndex=0;paint();const bottom=layer.getBoundingClientRect().bottom;if(bottom>innerHeight-8)layer.style.top=Math.max(8,rect.top-layer.getBoundingClientRect().height-4)+'px';search.focus();}
function openExport(button,run){close();exportMenu?.remove();const box=document.createElement('div');box.innerHTML=window.REVIEWED_V31_ASSETS.exportMenu;exportMenu=box.firstElementChild;exportMenu.classList.remove('ant-dropdown-hidden');exportMenu.dataset.v31Export='';const r=button.getBoundingClientRect();exportMenu.style.cssText='position:fixed;z-index:2300;left:'+r.x+'px;top:'+(r.bottom+4)+'px;min-width:160px';document.body.append(exportMenu);$('[role=menuitem]',exportMenu)?.addEventListener('click',()=>{exportMenu.remove();exportMenu=null;run();});}
window.DEMO_V31_LINKS={catalog,resolve:(type,id)=>catalog[type]?.find(r=>r.id===id)||null,open,close,openExport};
window.addEventListener('input',e=>{if(layer?.contains(e.target)&&e.target.matches('input')){e.stopImmediatePropagation();query=e.target.value;active=0;paint();}},true);
window.addEventListener('click',e=>{if(layer?.contains(e.target)){const option=e.target.closest('[data-v31-entity]');if(option){e.preventDefault();e.stopImmediatePropagation();choose(catalog[kind].find(r=>r.id===option.dataset.v31Entity));return;}if(e.target.closest('.kodo-new-input-clear-icon')){e.preventDefault();e.stopImmediatePropagation();query='';$('input',layer).value='';active=0;paint();$('input',layer).focus();return;}e.stopImmediatePropagation();return;}const clear=e.target.closest('[data-v31-clear]');if(clear){e.preventDefault();e.stopImmediatePropagation();anchor=clear.closest('[data-v31-linked]');kind=anchor.dataset.v31Linked;choose(null);return;}if(exportMenu?.contains(e.target))return;if(layer){close();}if(exportMenu){exportMenu.remove();exportMenu=null;}},true);
window.addEventListener('keydown',e=>{if(layer?.contains(e.target)){if(['ArrowDown','ArrowUp','Enter','Escape'].includes(e.key)){e.preventDefault();e.stopImmediatePropagation();if(e.key==='Escape'){close();return;}if(e.key==='Enter'){if(visible[active])choose(visible[active]);return;}active=Math.max(0,Math.min(visible.length-1,active+(e.key==='ArrowDown'?1:-1)));paint();}return;}if(e.key==='Escape'&&exportMenu){e.preventDefault();e.stopImmediatePropagation();exportMenu.remove();exportMenu=null;}},true);
})();
